const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const contractDir = path.join(
  repoRoot,
  'tests',
  'fixtures',
  'test-contracts',
  'plan00-evidence-contract'
);
const loadJson = (name) => JSON.parse(fs.readFileSync(path.join(contractDir, name), 'utf8'));

const schema = loadJson('schema-v1.json');
const snapshotA = loadJson('snapshot-v1.json');
const projectionA = loadJson('projection-v1.json');
const snapshotB = loadJson('snapshot-ineligible-v1.json');
const projectionB = loadJson('projection-ineligible-v1.json');
