describe('C1 ternary — idempotent and pre-admission playback verdicts', () => {
  test('a byte-identical ACK retransmission yields ONE authoritative row plus ONE idempotent audit row', () => {
    const entry = makeEntry();
    const ctx = composeCtx(entry);
    const op = {
      extractionTurnId: 't4',
      field: 'measured_zs_ohm',
      circuit: 9,
      boardId: null,
      ordinal: 0,
    };
    ctx.recordDelivery([op], { producerId: 'result_frame_confirmation', kind: 'confirmation' });
    const ack = { ok: true, turn: 't4', seq: 1 };
    const first = ctx.recordPlayback(ack, [op], {
      producerId: 'playback_ack_slot',
      source: 'ordinary',
    });
    const second = ctx.recordPlayback(ack, [op], {
      producerId: 'playback_ack_slot',
      source: 'ordinary',
    });
    expect(first).toBeTruthy();
    expect(second).toBeNull();
    expect(rowsOfKind(entry, 'playback_evidence')).toHaveLength(1);
    const idem = rowsOfKind(entry, 'playback_idempotent');
    expect(idem).toHaveLength(1);
    expect(idem[0]).toMatchObject({
      producer_id: 'playback_ack_slot',
      op_key: rowsOfKind(entry, 'playback_evidence')[0].op_key,
      ack_body_hash: rowsOfKind(entry, 'playback_evidence')[0].ack_body_hash,
    });
    // idempotent is benign — never invalidating
    expect(ctx.deliveryLedger.invalid).toBeNull();
  });

  test('pre-admission: a slot resolving to zero deliveries stays telemetry (no row, no latch), a later valid ACK succeeds', () => {
    const entry = makeEntry();
    const ctx = composeCtx(entry);
    // no deliveries at all — zero matches
    const miss = ctx.resolvePlaybackFromSlot({
      slot: { field: 'measured_zs_ohm', circuit: 1 },
      ackBody: { ok: true },
      source: 'ordinary',
    });
    expect(miss).toBeNull();
    expect(subRecords(entry)).toHaveLength(0);
    expect(ctx.deliveryLedger.invalid).toBeNull();
    // now a delivery lands and a valid ACK resolves
    const op = {
      extractionTurnId: 't5',
      field: 'measured_zs_ohm',
      circuit: 1,
      boardId: null,
      ordinal: 0,
    };
    ctx.recordDelivery([op], { producerId: 'result_frame_confirmation', kind: 'confirmation' });
    const hit = ctx.resolvePlaybackFromSlot({
      slot: { field: 'measured_zs_ohm', circuit: 1 },
      ackBody: { ok: true, n: 2 },
      source: 'ordinary',
    });
    expect(hit).toBeTruthy();
    expect(rowsOfKind(entry, 'playback_evidence')).toHaveLength(1);
    expect(ctx.deliveryLedger.invalid).toBeNull();
  });

  test('an integrity rejection at the ledger layer appends the rejected audit row and latches', () => {
    const entry = makeEntry();
    const ctx = composeCtx(entry);
    const op = { extractionTurnId: 't6', field: 'x', circuit: null, boardId: null, ordinal: 0 };
    // playback without ANY delivery_attempt — reaches the ledger directly
    const res = ctx.recordPlayback({ ok: true }, [op], {
      producerId: 'playback_ack_slot',
      source: 'ordinary',
    });
    expect(res).toBeNull();
    const rejected = rowsOfKind(entry, 'playback_rejected');
    expect(rejected).toHaveLength(1);
    expect(rejected[0]).toMatchObject({
      producer_id: 'playback_ack_slot',
      reason: 'playback_without_delivery_attempt',
    });
    expect(ctx.deliveryLedger.invalid?.reason).toBe('playback_without_delivery_attempt');
  });
});

describe('C5 — freeze-time canonical rows', () => {
  test('a healthy session appends NO freeze-time row and freezes revision-stable and eligible', () => {
    const entry = makeEntry();
    composeCtx(entry);
    const frozen = freezeEvidenceCompletion(entry, {
      sessionId: 'sess_h',
      boundary: 'session_stopped',
    });
    expect(frozen.eligible).toBe(true);
    expect(frozen.counts.revision_instability).toBe(0);
    expect(frozen.evidence.sub_records.filter((r) => r.kind === 'freeze_invalid')).toHaveLength(0);
  });

  test('an unconsumed fast-TTS provisional folds into the delivery_invalid latch at freeze time', () => {
    const entry = makeEntry();
    const ctx = composeCtx(entry);
    ctx.reserveFastTts({
      correlationId: 'corr_orphan',
      candidate: { field: 'measured_zs_ohm', circuit: 3, board_id: null, value: '0.4' },
    });
    const frozen = freezeEvidenceCompletion(entry, {
      sessionId: 'sess_p',
      boundary: 'session_stopped',
    });
    expect(ctx.deliveryLedger.invalid?.reason).toBe('fast_provisional_unconsumed');
    const freezeRows = frozen.evidence.sub_records.filter((r) => r.kind === 'freeze_invalid');
    expect(freezeRows).toEqual([
      expect.objectContaining({
        condition: 'delivery_invalid',
        reason: 'fast_provisional_unconsumed',
      }),
    ]);
    // The latch's own `eligible` flag deliberately keeps its quiescence-only
    // meaning; the C5 ineligibility rides the freeze row into the PROJECTION
    // (fold HOLD/INVALID), where 00C consumes it.
    expect(frozen.eligible).toBe(true);
    expect(buildEvidenceProjectionV1(frozen.candidate).eligible_for_family_credit).toBe(false);
    // the rows sit INSIDE the latched snapshot with stable revisions
    expect(frozen.counts.revision_instability).toBe(0);
    const latchedSnapshot = frozen.candidate; // observer.buildCandidate identity
    expect(latchedSnapshot.sub_records).toBe(frozen.evidence.sub_records);
  });

  test('a prepared-but-uncommitted dialogue delivery appends the outstanding-count freeze row', () => {
    const entry = makeEntry();
    const ctx = composeCtx(entry);
    const payload = { question: 'Zs for circuit 4 is 0.4.' };
    ctx.deliveryEmit.prepare(payload, { operations: [] });
    const frozen = freezeEvidenceCompletion(entry, {
      sessionId: 'sess_d',
      boundary: 'session_stopped',
    });
    const freezeRows = frozen.evidence.sub_records.filter((r) => r.kind === 'freeze_invalid');
    expect(freezeRows).toEqual([
      expect.objectContaining({ condition: 'delivery_prepared_outstanding', count: 1 }),
    ]);
    // quiescence-only latch flag; ineligibility rides the row into the fold
    expect(buildEvidenceProjectionV1(frozen.candidate).eligible_for_family_credit).toBe(false);
  });

  test('mutation and producer invalid latches surface as freeze-time rows', () => {
    const entry = makeEntry();
    const ctx = composeCtx(entry);
    ctx.mutationObserver.markInvalid('turn_scope_reentered', {});
    getLifecycleLedger(entry).producerInvalid = Object.freeze({
      reason: 'producer_double_completion',
      detail: null,
    });
    const frozen = freezeEvidenceCompletion(entry, {
      sessionId: 'sess_m',
      boundary: 'session_stopped',
    });
    const conditions = frozen.evidence.sub_records
      .filter((r) => r.kind === 'freeze_invalid')
      .map((r) => r.condition)
      .sort();
    expect(conditions).toEqual(['mutation_invalid', 'producer_invalid']);
    // quiescence-only latch flag; ineligibility rides the rows into the fold
    expect(buildEvidenceProjectionV1(frozen.candidate).eligible_for_family_credit).toBe(false);
  });
});

